import{_ as s,C as i,c as d,o as l,a3 as a,G as n,j as e,a as r}from"./chunks/framework.Dokpd4od.js";const w=JSON.parse('{"title":"Work orders","description":"","frontmatter":{},"headers":[],"relativePath":"master/supply-chain/manufacturing/workflows/work-orders.md","filePath":"master/supply-chain/manufacturing/workflows/work-orders.md","lastUpdated":1792041590000}'),g={name:"master/supply-chain/manufacturing/workflows/work-orders.md"};function u(h,t,c,p,m,k){const o=i("ImagePopup");return l(),d("div",null,[t[0]||(t[0]=a('<h1 id="work-orders" tabindex="-1">Work orders <a class="header-anchor" href="#work-orders" aria-label="Permalink to &quot;Work orders&quot;">​</a></h1><p>A work order is one step of a manufacturing order, run at one work center. If an MO says &quot;make 5 laptops&quot;, the work orders say &quot;assemble the parts at Assembly Station&quot; and &quot;test and pack at Quality &amp; Packing&quot;. Operators use them to start, pause and finish each step. Aureus records the time spent.</p><blockquote><p><strong>In simple words:</strong> A work order is one to-do item of an MO, with a timer.</p></blockquote><p>Open <code>Manufacturing → Operations → Work Orders</code>.</p><h2 id="settings" tabindex="-1">Settings <a class="header-anchor" href="#settings" aria-label="Permalink to &quot;Settings&quot;">​</a></h2><p>The <strong>Work Orders</strong> menu and the <strong>Work Orders</strong> tab on the MO need <strong>Work Orders</strong> on in <code>Manufacturing → Settings → Manage Operations</code>. The <strong>Blocked By</strong> order rules need <strong>Work Order Dependencies</strong> too. See <a href="./../get-started/manufacturing-settings.html">Manufacturing settings</a>.</p><p>You do not create work orders by hand. Aureus builds one for each operation of the bill of materials when the MO is created. See <a href="./../advanced-configuration/operations.html">Operations</a>.</p><h2 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to &quot;Overview&quot;">​</a></h2>',8)),n(o,{src:"/images1/manufacturing/wo_list.png",alt:"Work Orders list with MO/2 rows for Assemble Components and Test & Pack, tabs and summary row visible"}),t[1]||(t[1]=a('<ul><li><strong>Tabs:</strong> <strong>Default</strong>, <strong>To Do</strong>, <strong>Draft</strong>, <strong>Done</strong>, <strong>Cancelled</strong>.</li><li><strong>Columns:</strong> <strong>Operation</strong>, <strong>Work Center</strong>, <strong>Manufacturing Order</strong>, <strong>Product</strong>, <strong>Quantity Remaining</strong>, <strong>Expected Duration</strong>, <strong>Real Duration</strong>, <strong>Status</strong>. A summary row adds up the durations.</li><li><strong>Row actions:</strong> <strong>View</strong>, <strong>Edit</strong>. Icon buttons start, pause and finish the work order.</li></ul><p>There is no create button.</p><h2 id="states" tabindex="-1">States <a class="header-anchor" href="#states" aria-label="Permalink to &quot;States&quot;">​</a></h2><table tabindex="0"><thead><tr><th>State</th><th>Meaning</th></tr></thead><tbody><tr><td><strong>Waiting for another work order</strong></td><td>An earlier work order in <strong>Blocked By</strong> is not finished.</td></tr><tr><td><strong>Waiting for components</strong></td><td>Components are not reserved yet.</td></tr><tr><td><strong>Ready</strong></td><td>You can start.</td></tr><tr><td><strong>In Progress</strong></td><td>The timer runs.</td></tr><tr><td><strong>Finished</strong></td><td>The step is complete.</td></tr><tr><td><strong>Cancelled</strong></td><td>The MO was cancelled.</td></tr></tbody></table><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Waiting for another work order → Waiting for components → Ready → In Progress → Finished</span></span></code></pre></div><h2 id="run-a-work-order" tabindex="-1">Run a work order <a class="header-anchor" href="#run-a-work-order" aria-label="Permalink to &quot;Run a work order&quot;">​</a></h2><p>Scenario: run <strong>Assemble Components</strong> of <strong>MO/2</strong>.</p><ol><li>Open <code>Manufacturing → Operations → Work Orders</code>.</li><li>Find the row <strong>Assemble Components</strong> that is <strong>Ready</strong>.</li><li>Click the <strong>Start</strong> icon. <strong>Status</strong> becomes <strong>In Progress</strong> and the MO becomes <strong>In Progress</strong>.</li></ol>',8)),n(o,{src:"/images1/manufacturing/wo_start.png",alt:"Work Orders list row Ready with the start icon highlighted"}),t[2]||(t[2]=e("ol",{start:"4"},[e("li",null,[r("Click the "),e("strong",null,"Pause"),r(" icon for a break. The time log closes. Click start to resume.")]),e("li",null,[r("Click the "),e("strong",null,"Done"),r(" icon when the step is complete. "),e("strong",null,"Status"),r(" becomes "),e("strong",null,"Finished"),r(".")])],-1)),n(o,{src:"/images1/manufacturing/wo_done.png",alt:"Work order row In Progress with pause and done icons visible"}),t[3]||(t[3]=e("div",{class:"warning custom-block"},[e("p",{class:"custom-block-title"},"WARNING"),e("p",null,'If the work center is blocked, Aureus refuses to start. It says "Please unblock the work center to start the work order."')],-1)),t[4]||(t[4]=e("p",null,[r("The same icons are on the "),e("strong",null,"Work Orders"),r(" tab of the MO.")],-1)),t[5]||(t[5]=e("h2",{id:"view-a-work-order",tabindex:"-1"},[r("View a work order "),e("a",{class:"header-anchor",href:"#view-a-work-order","aria-label":'Permalink to "View a work order"'},"​")],-1)),t[6]||(t[6]=e("p",null,[r("Click "),e("strong",null,"View"),r(" on a row.")],-1)),n(o,{src:"/images1/manufacturing/wo_view.png",alt:"Work order view page for MO/2 - Assemble Components: state bar and General section"}),t[7]||(t[7]=a('<p>The <strong>General</strong> section shows:</p><ul><li><strong><em>Work Order:</em></strong> The operation name.</li><li><strong><em>Work Center:</em></strong> Where it runs.</li><li><strong><em>Product:</em></strong> The product you make.</li><li><strong><em>Quantity:</em></strong> The quantity to process.</li><li><strong><em>Manufacturing Order:</em></strong> The parent MO.</li><li><strong><em>Lot/Serial Number:</em></strong> The lot or serial, if the product is tracked.</li><li><strong><em>Start Date</em></strong> and <strong><em>End Date</em>:</strong> The planned window. See <a href="./plan-and-schedule.html">Plan and schedule</a>.</li><li><strong><em>Expected Duration</em></strong> and <strong><em>Real Duration</em>:</strong> Planned and tracked time.</li></ul><h3 id="time-tracking" tabindex="-1">Time Tracking <a class="header-anchor" href="#time-tracking" aria-label="Permalink to &quot;Time Tracking&quot;">​</a></h3>',3)),n(o,{src:"/images1/manufacturing/wo_time_tracking.png",alt:"Time Tracking tab of a work order that was started and paused, with log rows and Real Duration"}),t[8]||(t[8]=a('<p>Each start and pause makes a log row: <strong>User</strong>, <strong>Duration</strong>, <strong>Start Date</strong>, <strong>End Date</strong>, <strong>Productivity</strong>. <strong>Real Duration</strong> adds them up.</p><h3 id="components" tabindex="-1">Components <a class="header-anchor" href="#components" aria-label="Permalink to &quot;Components&quot;">​</a></h3><p>Lists the components used by this step.</p><h3 id="work-instruction" tabindex="-1">Work Instruction <a class="header-anchor" href="#work-instruction" aria-label="Permalink to &quot;Work Instruction&quot;">​</a></h3>',4)),n(o,{src:"/images1/manufacturing/wo_work_instruction.png",alt:"Work Instruction tab showing the worksheet of the operation"}),t[9]||(t[9]=a('<p>Shows the worksheet of the operation: a PDF, a Google Slide or text. Set it on the operation. See <a href="./../advanced-configuration/operations.html">Operations</a>.</p><h3 id="blocked-by" tabindex="-1">Blocked By <a class="header-anchor" href="#blocked-by" aria-label="Permalink to &quot;Blocked By&quot;">​</a></h3><p>Lists the work orders that must finish first. While any of them is open, this one waits.</p><h2 id="expected-vs-real-duration" tabindex="-1">Expected vs real duration <a class="header-anchor" href="#expected-vs-real-duration" aria-label="Permalink to &quot;Expected vs real duration&quot;">​</a></h2><p><strong>Expected Duration</strong> is the plan. <strong>Real Duration</strong> is the time your team logged. Compare them to improve the default duration on the operation. See <a href="./../basic-setup/manufacturing-order-costs.html">Manufacturing order costs</a>.</p><h2 id="behind-the-scenes" tabindex="-1">Behind the scenes <a class="header-anchor" href="#behind-the-scenes" aria-label="Permalink to &quot;Behind the scenes&quot;">​</a></h2><p>Start sets the work order and the MO to <strong>In Progress</strong>. Pause ends the open time log. Done sets <strong>Finished</strong>.</p><h2 id="see-also" tabindex="-1">See also <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;See also&quot;">​</a></h2><ul><li><a href="./manufacturing-orders.html">Manufacturing orders</a></li><li><a href="./plan-and-schedule.html">Plan and schedule</a></li><li><a href="./produce-and-consume.html">Produce and consume</a></li><li><a href="./../advanced-configuration/work-centers.html">Work centers</a></li></ul>',9))])}const b=s(g,[["render",u]]);export{w as __pageData,b as default};
